from datetime import datetime, timedelta, date
import calendar
import math

WEEKDAY_MAP = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _parse_local(s):
    return datetime.strptime(s, "%Y-%m-%dT%H:%M")


def _parse_utc(s):
    return datetime.strptime(s, "%Y-%m-%dT%H:%MZ")


def _fmt_utc(dt):
    return dt.strftime("%Y-%m-%dT%H:%MZ")


def _days_in_month(y, m):
    return calendar.monthrange(y, m)[1]


def _resolve_month_day(y, m, spec):
    if spec > 0:
        dim = _days_in_month(y, m)
        return spec if spec <= dim else None
    else:
        dim = _days_in_month(y, m)
        d = dim - (-spec - 1)
        return d if d >= 1 else None


def _resolve_nth_weekday(y, m, weekday, n):
    dim = _days_in_month(y, m)
    first = date(y, m, 1)
    first_wd = first.weekday()
    if n > 0:
        diff = (weekday - first_wd) % 7
        day = 1 + diff + (n - 1) * 7
        return day if day <= dim else None
    else:
        last = date(y, m, dim)
        last_wd = last.weekday()
        diff = (last_wd - weekday) % 7
        day = dim - diff + (n + 1) * 7
        return day if day >= 1 else None


def _iter_daily(start_local, interval, skip_to):
    current = start_local
    if skip_to is not None and skip_to > current:
        delta_days = (skip_to - current) / timedelta(days=1)
        k = math.ceil(delta_days / interval)
        if k > 0:
            current = start_local + timedelta(days=int(k) * interval)
        while current < skip_to:
            current += timedelta(days=interval)
    while True:
        yield current
        current += timedelta(days=interval)


def _iter_weekly(rule, start_local, interval, skip_to):
    by_wd_strs = rule.get("by_weekday")
    if by_wd_strs is None:
        by_wd = [start_local.weekday()]
    else:
        by_wd = sorted(WEEKDAY_MAP[s] for s in by_wd_strs)

    hour, minute = start_local.hour, start_local.minute
    start_date = start_local.date()
    week0_monday = start_date - timedelta(days=start_date.weekday())

    if skip_to is not None and skip_to > start_local:
        skip_date = skip_to.date()
        skip_week_monday = skip_date - timedelta(days=skip_date.weekday())
        skip_week_num = (skip_week_monday - week0_monday).days // 7
        if skip_week_num < 0:
            skip_week_num = 0
        rem = skip_week_num % interval
        if rem != 0:
            skip_week_num += interval - rem
        start_week = skip_week_num
    else:
        start_week = 0

    week_num = start_week
    while True:
        week_monday = week0_monday + timedelta(weeks=week_num)
        for wd in by_wd:
            occ_date = week_monday + timedelta(days=wd)
            occ = datetime(occ_date.year, occ_date.month, occ_date.day, hour, minute)
            if week_num == 0 and occ < start_local:
                continue
            if skip_to is not None and occ < skip_to:
                continue
            yield occ
        week_num += interval


def _iter_monthly(rule, start_local, interval, skip_to):
    hour, minute = start_local.hour, start_local.minute
    start_date = start_local.date()
    start_year, start_month = start_date.year, start_date.month

    use_nth = "by_nth_weekday" in rule
    if use_nth:
        nth_n, nth_wd_str = rule["by_nth_weekday"]
        nth_wd = WEEKDAY_MAP[nth_wd_str]
    elif "by_month_day" in rule:
        day_specs = rule["by_month_day"]
    else:
        day_specs = [start_date.day]

    if skip_to is not None and skip_to > start_local:
        skip_date = skip_to.date()
        skip_month_offset = (skip_date.year - start_year) * 12 + (skip_date.month - start_month)
        if skip_month_offset < 0:
            skip_month_offset = 0
        rem = skip_month_offset % interval
        if rem != 0:
            skip_month_offset += interval - rem
        start_month_offset = skip_month_offset
    else:
        start_month_offset = 0

    month_offset = start_month_offset
    while True:
        total = (start_month - 1) + month_offset
        y = start_year + total // 12
        m = total % 12 + 1

        if use_nth:
            d = _resolve_nth_weekday(y, m, nth_wd, nth_n)
            days = [d] if d is not None else []
        else:
            days = []
            seen = set()
            for spec in day_specs:
                d = _resolve_month_day(y, m, spec)
                if d is not None and d not in seen:
                    days.append(d)
                    seen.add(d)
            days.sort()

        for d in days:
            try:
                occ_date = date(y, m, d)
            except ValueError:
                continue
            occ = datetime(y, m, d, hour, minute)
            if month_offset == 0 and occ < start_local:
                continue
            if skip_to is not None and occ < skip_to:
                continue
            yield occ

        month_offset += interval


def _iter_yearly(start_local, interval, skip_to):
    hour, minute = start_local.hour, start_local.minute
    start_year = start_local.year
    month = start_local.month
    day = start_local.day

    year = start_year
    if skip_to is not None and skip_to > start_local:
        diff = skip_to.year - start_year
        if diff > 0:
            k = math.ceil(diff / interval)
            year = start_year + int(k) * interval

    while True:
        try:
            occ_date = date(year, month, day)
        except ValueError:
            year += interval
            continue
        occ = datetime(year, month, day, hour, minute)
        if skip_to is not None and occ < skip_to:
            year += interval
            continue
        yield occ
        year += interval


def _iter_freq(rule, start_local, skip_to):
    freq = rule["freq"]
    interval = rule.get("interval", 1)
    if freq == "daily":
        yield from _iter_daily(start_local, interval, skip_to)
    elif freq == "weekly":
        yield from _iter_weekly(rule, start_local, interval, skip_to)
    elif freq == "monthly":
        yield from _iter_monthly(rule, start_local, interval, skip_to)
    elif freq == "yearly":
        yield from _iter_yearly(start_local, interval, skip_to)


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    freq = rule["freq"]
    interval = rule.get("interval", 1)

    if freq not in ("daily", "weekly", "monthly", "yearly"):
        raise ValueError(f"Unknown freq: {freq}")
    if interval < 1:
        raise ValueError(f"interval must be >= 1, got {interval}")
    if "count" in rule and "until" in rule:
        raise ValueError("Both 'count' and 'until' are present")
    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError("Both 'by_month_day' and 'by_nth_weekday' are present")

    offset = rule["utc_offset_minutes"]
    start_local = _parse_local(rule["start"])
    ws_utc = _parse_utc(window_start)
    we_utc = _parse_utc(window_end)
    offset_td = timedelta(minutes=offset)
    ws_local = ws_utc + offset_td
    we_local = we_utc + offset_td

    count_limit = rule.get("count")
    until_local = _parse_local(rule["until"]) if "until" in rule else None
    exclude_set = frozenset(_parse_local(ex) for ex in rule.get("exclude", []))

    result = []

    if count_limit is not None:
        count_used = 0
        for occ in _iter_freq(rule, start_local, None):
            if until_local is not None and occ > until_local:
                break
            count_used += 1
            if count_used > count_limit:
                break
            if ws_local <= occ < we_local:
                if occ not in exclude_set:
                    result.append(occ)
    else:
        skip_to = max(start_local, ws_local)
        for occ in _iter_freq(rule, start_local, skip_to):
            if occ >= we_local:
                break
            if until_local is not None and occ > until_local:
                break
            if occ not in exclude_set:
                result.append(occ)

    result_utc = sorted(occ - offset_td for occ in result)
    return [_fmt_utc(t) for t in result_utc]
